CATEGORIES = ('VALID', 'MISSING', 'MALFORMED', 'OUT_OF_DOMAIN', 'OS_ERROR', 'TIMEOUT', 'NONZERO_EXIT', 'OUTPUT_CAP', 'INTERRUPTED', 'PERMISSION_DENIED', 'MEMORY_ERROR', 'UNEXPECTED_EXCEPTION')
MAX_ROWS = 256
