import json
import os
import platform
import sqlite3
import sys
import unittest
TYPE_NAMES = ('NoneType', 'bool', 'int', 'float', 'str', 'bytes', 'list', 'tuple', 'dict', 'set', 'type', 'OTHER', 'NOT_CAPTURED')
EXCEPTIONS = ('AssertionError', 'TypeError', 'ValueError', 'RuntimeError', 'OSError', 'PermissionError', 'FileNotFoundError', 'MemoryError', 'RecursionError', 'OperationalError', 'DatabaseError', 'IntegrityError', 'OTHER', 'NOT_CAPTURED')
ASSERTIONS = ('assertEqual', '_baseAssertEqual', 'assertIsInstance', 'assertTrue', 'assertFalse')
UNIT_FUNCTIONS = ASSERTIONS + ('fail', '_callTestMethod', '_callSetUp', '_callTearDown', 'run', 'testPartExecutor', '_raiseFailure', '__exit__', 'assertRaises', 'assertRaisesRegex')
MAX_FAILURES = 6
MAX_FRAMES = 5
MAX_CASE_RECORDS = 124
OUTCOMES = ('failure', 'error', 'subtest_failure', 'subtest_error', 'unexpected_success')
REASONS = ('EXCEPTION_CATEGORY', 'ASSERTION_FAILED', 'EQUALITY_TYPES_DIFFER', 'EQUALITY_VALUES_DIFFER', 'INSTANCE_CHECK_FAILED', 'TRUTH_CHECK_FAILED', 'EXPECTED_EXCEPTION_ASSERTION_FAILED', 'UNEXPECTED_SUCCESS')

def assertion_reason(detail):
    if detail['outcome'] == 'unexpected_success':
        return 'UNEXPECTED_SUCCESS'
    if detail['exception'] != 'AssertionError':
        return 'EXCEPTION_CATEGORY'
    semantics = detail['type_semantics']
    if semantics == 'first_second_operands':
        return 'EQUALITY_TYPES_DIFFER' if detail['actual_type'] != detail['expected_type'] else 'EQUALITY_VALUES_DIFFER'
    if semantics == 'instance_check':
        return 'INSTANCE_CHECK_FAILED'
    if semantics == 'truth_check':
        return 'TRUTH_CHECK_FAILED'
    if any((frame['file'] == 'unittest' and frame['function'] in ('assertRaises', 'assertRaisesRegex', '__exit__') for frame in detail['stack'])):
        return 'EXPECTED_EXCEPTION_ASSERTION_FAILED'
    return 'ASSERTION_FAILED'

def record_key(detail, policy):
    case = policy['cases'].index(detail['case']) if detail['case'] in policy['cases'] else -1
    return (case, OUTCOMES.index(detail['outcome']), EXCEPTIONS.index(detail['exception']), REASONS.index(assertion_reason(detail)))

def type_name(value):
    for cls in (type(None), bool, int, float, str, bytes, list, tuple, dict, set, type):
        if type(value) is cls:
            return cls.__name__
    return 'OTHER'

def class_name(value):
    for cls in (type(None), bool, int, float, str, bytes, list, tuple, dict, set, type):
        if value is cls:
            return cls.__name__
    return 'OTHER'

def exception_name(value):
    for cls in (AssertionError, TypeError, ValueError, RuntimeError, OSError, PermissionError, FileNotFoundError, MemoryError, RecursionError, sqlite3.OperationalError, sqlite3.DatabaseError, sqlite3.IntegrityError):
        if value is cls:
            return cls.__name__
    return 'OTHER'

class FactsResult(unittest.TestResult):

    def __init__(self, policy):
        super().__init__()
        self.policy = policy
        self.facts = []
        self.case_records = {}
        self.case_records_omitted = 0
        self.issue_count = 0
        self.unrecognized_cases = 0
        self.failure_count = self.error_count = self.unexpected_count = 0

    def _exc_info_to_string(self, err, test):
        return 'SANITIZED_SYNTHETIC_FAILURE'

    def record(self, test, outcome, err=None):
        self.issue_count += 1
        case = getattr(test, 'test_case', test)
        identifier = case.__class__.__module__ + '.' + case.__class__.__name__ + '.' + getattr(case, '_testMethodName', '')
        if identifier not in self.policy['cases']:
            self.unrecognized_cases += 1
            identifier = 'UNRECOGNIZED_CASE'
        facts = dict(case=identifier, outcome=outcome, exception='NOT_CAPTURED', actual_type='NOT_CAPTURED', expected_type='NOT_CAPTURED', type_semantics='not_captured', stack=[], omitted_frames=0)
        if err:
            facts['exception'] = exception_name(err[0])
            tb = err[2]
            frames = []
            while tb:
                code = tb.tb_frame.f_code
                (file, function) = (code.co_filename, code.co_name)
                spec = self.policy['files'].get(file)
                if spec and (function in spec['functions'] or function == '<module>') and (0 < tb.tb_lineno <= spec['lines']):
                    frames.append(dict(file=file, function=function, line=tb.tb_lineno))
                elif file.startswith(os.path.dirname(unittest.__file__) + os.sep) and function in UNIT_FUNCTIONS:
                    frames.append(dict(file='unittest', function=function, line=tb.tb_lineno))
                else:
                    facts['omitted_frames'] += 1
                if file.startswith(os.path.dirname(unittest.__file__) + os.sep):
                    operands = tb.tb_frame.f_locals
                    if function in ('assertEqual', '_baseAssertEqual'):
                        facts.update(actual_type=type_name(operands.get('first')), expected_type=type_name(operands.get('second')), type_semantics='first_second_operands')
                    elif function == 'assertIsInstance':
                        facts.update(actual_type=type_name(operands.get('obj')), expected_type=class_name(operands.get('cls')), type_semantics='instance_check')
                    elif function in ('assertTrue', 'assertFalse'):
                        facts.update(actual_type=type_name(operands.get('expr')), expected_type='bool', type_semantics='truth_check')
                tb = tb.tb_next
