def bounded_metadata(path, maximum):
    D.metric('metadata_cap', maximum)
    with open(path, 'rb') as stream:
        value = observed_bytes(stream.read(maximum + 1), maximum + 1)
    if len(value) > maximum:
        raise ReadinessHold('OUTPUT_CAP')
    return value.decode('ascii')

def check(stage):
    stage.at('preflight.identity')
    stage.need(D.guard(34, sys.platform == 'linux' and observed('uid', os.geteuid()) == 0))
    stage.need(D.guard(35, pwd.getpwnam('nobody').pw_uid == 65534))
    stage.at('preflight.metadata')
    observed_state('architecture', platform.machine())
    observed_state('platform', sys.platform)
    observed_version('python', sys.version.split()[0])
    observed_version('sqlite', sqlite3.sqlite_version)
    stage.need(D.guard(36, platform.machine() == 'x86_64'))
    stage.need(D.guard(37, sys.version.split()[0] == '3.11.2' and sqlite3.sqlite_version == '3.40.1'))
    stage.at('preflight.systemd')
    result = observed_run(['/usr/bin/systemctl', '--version'], stdin=subprocess.DEVNULL, capture_output=True, timeout=3, env={'PATH': '/usr/bin:/bin', 'LC_ALL': 'C'})
    stage.need(D.guard(38, result.returncode == 0), 'NONZERO_EXIT')
    stage.need(D.guard(39, len(result.stdout) + len(result.stderr) <= 4096), 'OUTPUT_CAP')
    rows = result.stdout.decode('ascii').splitlines()
    stage.need(D.guard(40, bool(rows) and len(rows[0].split()) >= 2), 'MALFORMED')
    version = rows[0].split()[1]
    stage.need(D.guard(41, version.isascii() and version.isdigit() and (len(version) <= 5)), 'MALFORMED')
    D.metric('systemd_version', int(version))
    stage.need(D.guard(42, version == '252'))
    manager = observed_run(['/usr/bin/systemctl', 'show', '--property=Version', '--value'], stdin=subprocess.DEVNULL, capture_output=True, timeout=3, env={'PATH': '/usr/bin:/bin', 'LC_ALL': 'C'})
    stage.need(D.guard(43, manager.returncode == 0), 'NONZERO_EXIT')
    stage.need(D.guard(44, len(manager.stdout) + len(manager.stderr) <= 4096), 'OUTPUT_CAP')
    manager_major = manager.stdout.strip().split(b'.')[0]
    if manager_major.isdigit() and len(manager_major) <= 5:
        D.metric('systemd_manager_version', int(manager_major))
    else:
        D.metric('systemd_manager_version', status='MALFORMED')
    stage.need(D.guard(45, manager.stdout.strip().split(b'.')[0] == b'252'))
    stage.need(D.guard(46, os.readlink('/proc/1/exe') in ('/usr/lib/systemd/systemd', '/lib/systemd/systemd')))
    readiness = observed_run(['/usr/bin/systemctl', 'is-system-running'], stdin=subprocess.DEVNULL, capture_output=True, timeout=3, env={'PATH': '/usr/bin:/bin', 'LC_ALL': 'C'})
    stage.need(D.guard(47, len(readiness.stdout) + len(readiness.stderr) <= 4096), 'OUTPUT_CAP')
    stage.need(D.guard(48, readiness.returncode == 0 and readiness.stdout.strip() == b'running'))
    stage.at('preflight.controllers')
    controllers = bounded_metadata('/sys/fs/cgroup/cgroup.controllers', 256).split()
    stage.need(D.guard(49, {'cpu', 'memory', 'pids'} <= set(controllers)))
    stage.at('preflight.memory')
    observations = sample(lambda path, cap: bounded_metadata(path, cap))
    for (name, (status, value)) in observations.items():
        D.metric(name, value, status)
    for (name, target_stage) in (('mem_available', 'preflight.memory'), ('memory_full_avg10', 'preflight.pressure'), ('io_some_avg10', 'preflight.pressure')):
        stage.at(target_stage)
        (status, value) = observations[name]
        if status != 'VALID':
            raise GateError(stage.name, 'OUTPUT_CAP' if status == 'OUTPUT_CAP' else status if status in ERRORS else 'MALFORMED')
        if name == 'mem_available':
            stage.need(D.guard(50, value >= 8589934592))
        else:
            stage.need(D.guard(51, value < (1 if name == 'memory_full_avg10' else 5)))
    stage.at('preflight.paths')
    stage.need(D.guard(52, all((pathlib.Path(path).exists() for path in ('/usr/bin/python3', '/usr/bin/systemd-run', '/usr/bin/systemctl', '/usr/bin', '/usr/lib', '/lib', '/lib64', '/etc/ld.so.cache')))))
    stage.need(D.guard(53, not pathlib.Path(PREFIX).exists() and (not pathlib.Path(PREFIX).is_symlink())))
    stage.at('preflight.unit')
    state = selected_unit(stage)
    stage.need(D.guard(54, observed_state('LoadState', state.get('LoadState')) == 'not-found' and observed_state('MainPID', state.get('MainPID', '0')) == '0'))
    return {'admitted': True, 'scope': 'DISPOSABLE_HOSTED_DEBIAN12_SYNTHETIC_ONLY', 'exact_runtime': {'Python': '3.11.2', 'SQLite': '3.40.1', 'systemd': '252', 'architecture': 'x86_64'}, 'fixtures_started': False, 'production_data_access': False}
